\begin{figure}[!htbp]
\centering
\includegraphics[width=\linewidth]{figs/downstream_performance_across_llms/preview.pdf}
\caption{Downstream performance across LLMs and tasks. Source Average rows for RouterBSI\_top5 with SkillSight retrieval; accuracy pools correct predictions over 748 test tasks across six datasets for each model, rather than averaging dataset accuracies equally. No uncertainty estimate is displayed. Exactly three bars show RouterBSI\_top5, one per LLM backbone; no baseline or per-dataset bars are included.}
\label{fig:downstream_performance_across_llms}
\end{figure}

\begin{figure}[!htbp]
\centering
\includegraphics[width=\linewidth]{figs/mbr_replay_f1_all_splits/preview.pdf}
\caption{Replay and validation-gate F1 across train, validation, and test splits. Source Dataset=Average rows for train, validation, and test; train uses prequential scores, validation uses ledger-accepted-candidate scores, and test uses accepted-candidate scores. Initial and final are snapshot checkpoints (plotted at 0 and 11); iterations 1–10 use their source evaluation stage. Lines show F1 means; shaded bands show mean ± one population standard deviation from the supplied variance (not confidence intervals); three observed runs per checkpoint.}
\label{fig:mbr_replay_f1_all_splits}
\end{figure}

\begin{figure}[!htbp]
\centering
\includegraphics[width=\linewidth]{figs/mbr_replay_validation_std/preview.pdf}
